@startuml

enum SubscriptionType {
  MONTHLY
  ANNUAL
}

enum ServiceType {
  WEIGHT_ROOM
  SWIMMING_POOL
  CLIMBING_WALL
  SAUNA
  TURKISH_BATH
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Subscription {
  + type : SubscriptionType
}

class Service {
  + type : ServiceType
}

class WorkoutPlan {
  + frequency : int
}

class Exercise {
  + name : string
  + repetitions : int
}

class MedicalCheck {
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class MedicalStaff {
}

class Diet {
}

class Gym {
  + computeMonthlyBalance() : float
  + computeYearlyBalance() : float
  + sendArrearsReminder()
  + sendMedicalCheckReminder()
}

Customer "1" -- "1" Subscription
Customer "1" -- "*" Service
Customer "1" -- "0..1" WorkoutPlan
Customer "1" -- "0..*" MedicalCheck
Customer "0..*" -- "1" MedicalStaff : requests service
MedicalStaff "1" -- "*" Diet : defines
MedicalStaff "1" -- "*" MedicalCheck : performs
WorkoutPlan "1" *-- "*" Exercise
Gym "1" -- "*" Customer
Gym "1" -- "*" MedicalStaff

@enduml

